 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+1;var p=W+"/request.txt";if(!File.Exists(p))return;string c=File.ReadAllText(p).Trim();File.Delete(p);try{if(c=="create")Create();else if(c=="capture")Capture();else if(c=="validate")Validate();else if(c=="build")BuildWeb();else if(c=="refine")Refine();else if(c=="polish")Polish();else if(c=="grounding")Grounding();else if(c=="reopen")Reopen();else if(c=="framepower")FramePower();else if(c=="save")EditorSceneManager.SaveScene(Open());else throw new Exception(c);}catch(Exception e){File.WriteAllText(O+"/automation-error.txt",e.ToString());Debug.LogException(e);}}
 static Color Hex(string h){ColorUtility.TryParseHtmlString(h,out var c);return c;}
 static float Height(float x,float z){float h=z<=0?0:z<=20?z/20:z<=55?1+(z-20)*3/35:z<=85?4:z<=105?4+(z-85)*4/20:z<=120?8+(z-105)*4/15:12;float e=Mathf.SmoothStep(0,1,Mathf.InverseLerp(30,70,x));return h*Mathf.Lerp(1,.35f,e)+.25f*e*Mathf.Clamp01(z/20f);}
 static Vector3 At(float x,float z,float y=0){return new Vector3(x,Height(x,z)+y,z);}
 static float Seg(Vector2 p,Vector2 a,Vector2 b){var d=b-a;return Vector2.Distance(p,a+d*Mathf.Clamp01(Vector2.Dot(p-a,d)/d.sqrMagnitude));}
 static float RouteDistance(Vector2 p){float d=1000;for(int i=0;i<route.Length-1;i++)d=Mathf.Min(d,Seg(p,route[i],route[i+1]));return d;}
 static float PadDistance(Vector2 p){float d=1000;for(int i=0;i<centers.Length;i++){var q=new Vector2(Mathf.Max(0,Mathf.Abs(p.x-centers[i].x)-halfPads[i].x),Mathf.Max(0,Mathf.Abs(p.y-centers[i].y)-halfPads[i].y));d=Mathf.Min(d,q.magnitude);}return d;}
 static float ArtHeight(float x,float z){float protect=Mathf.SmoothStep(0,1,Mathf.InverseLerp(10,20,RouteDistance(new Vector2(x,z))))*Mathf.SmoothStep(0,1,Mathf.InverseLerp(3,9,PadDistance(new Vector2(x,z))));float macro=(Mathf.PerlinNoise((x+200)*.024f,(z+200)*.018f)-.5f)*.7f;float channel=-.35f*Mathf.Exp(-Mathf.Pow((x+37+Mathf.Sin(z*.06f)*9)/4,2))*Mathf.Clamp01((z-30)/30);return Height(x,z)+(macro+channel)*protect;}
