 // Chamfered rectangular pressurized cross-section, extruded along X. Shared by habitat and agricultural shell.
 static Mesh Shell(string name,float length,float height,float depth,float bevel){var yz=new Vector2[]{new Vector2(-depth/2+bevel,0),new Vector2(depth/2-bevel,0),new Vector2(depth/2,bevel),new Vector2(depth/2,height-bevel),new Vector2(depth/2-bevel,height),new Vector2(-depth/2+bevel,height),new Vector2(-depth/2,height-bevel),new Vector2(-depth/2,bevel)};var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();Action<Vector3,Vector3,Vector3,Vector3> quad=(a,b,c,d)=>{int k=v.Count;v.AddRange(new[]{a,b,c,d});uv.AddRange(new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up});tri.AddRange(new[]{k,k+2,k+1,k,k+3,k+2});};for(int j=0;j<8;j++){var a=yz[j];var b=yz[(j+1)%8];quad(new Vector3(-length/2,a.y,a.x),new Vector3(-length/2,b.y,b.x),new Vector3(length/2,b.y,b.x),new Vector3(length/2,a.y,a.x));}for(int side=0;side<2;side++){float x=(side==0?-1:1)*length/2;for(int j=0;j<8;j++){int k=v.Count;var a=yz[j];var b=yz[(j+1)%8];v.AddRange(new[]{new Vector3(x,height/2,0),new Vector3(x,a.y,a.x),new Vector3(x,b.y,b.x)});uv.AddRange(new[]{new Vector2(.5f,.5f),new Vector2(a.x/depth+.5f,a.y/height),new Vector2(b.x/depth+.5f,b.y/height)});tri.AddRange(side==1?new[]{k,k+2,k+1}:new[]{k,k+1,k+2});}}var m=new Mesh{name=name};m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(tri,0);m.RecalculateNormals();m.RecalculateTangents();SaveMesh(m,"Architecture");return m;}
 // Ring-based angular eroded form; a shared family has three geometric LODs.
 static Mesh Rock(string name,int sides,int rings,int seed,bool layered){var random=new System.Random(seed);var verts=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();for(int r=0;r<=rings;r++){float y=(float)r/rings;float radius=r==0?.78f:r==rings?.22f:Mathf.Sin(y*Mathf.PI)*.25f+.65f;for(int s=0;s<sides;s++){float angle=(float)s/sides*Mathf.PI*2;float jitter=.85f+(float)random.NextDouble()*.3f;float rr=radius*jitter;if(layered){float fracture=.9f+.11f*Mathf.Sin(angle*3+seed)+.07f*Mathf.Cos(angle*7);rr=(1-.28f*y)*fracture+.025f*Mathf.Sin(y*37+angle*2);y=y*(.95f+.05f*Mathf.Sin(angle*2+seed));}verts.Add(new Vector3(Mathf.Cos(angle)*rr+(y-.5f)*.12f,y,Mathf.Sin(angle)*rr*.8f));uv.Add(new Vector2((float)s/sides,y));}}for(int r=0;r<rings;r++)for(int s=0;s<sides;s++){int a=r*sides+s,b=r*sides+(s+1)%sides,c=(r+1)*sides+s,d=(r+1)*sides+(s+1)%sides;tris.AddRange(new[]{a,c,b,b,c,d});}for(int s=1;s<sides-1;s++){tris.AddRange(new[]{0,s,(s+1)});int k=rings*sides;tris.AddRange(new[]{k,k+s+1,k+s});}var m=new Mesh{name=name};m.SetVertices(verts);m.SetUVs(0,uv);m.SetTriangles(tris,0);m.RecalculateNormals();m.RecalculateTangents();SaveMesh(m,"Rocks");return m;}
 static Texture2D Texture(string name,int size,Func<float,float,Color> sample,bool normal=false,bool clamp=false){var t=new Texture2D(size,size,TextureFormat.RGBA32,true,normal);var pixels=new Color[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)pixels[y*size+x]=sample((float)x/size,(float)y/size);t.SetPixels(pixels);t.Apply();string p=F+"/Materials/"+name+".png";File.WriteAllBytes(p,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(p);imp.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;imp.sRGBTexture=!normal;imp.mipmapEnabled=true;imp.isReadable=false;imp.textureCompression=TextureImporterCompression.Compressed;imp.compressionQuality=65;imp.wrapMode=clamp?TextureWrapMode.Clamp:TextureWrapMode.Repeat;imp.filterMode=FilterMode.Trilinear;imp.maxTextureSize=size;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(p);}
 static float Noise(float u,float v){return Mathf.PerlinNoise(u*17+31,v*17+53)*.5f+Mathf.PerlinNoise(u*57+61,v*57+23)*.3f+Mathf.PerlinNoise(u*183,v*183)*.2f;}
