 var macro=Texture("Regolith_Macro_Pathwear_1024",1024,(u,v)=>{float x=u*250-125,z=v*250-125;float n=Noise(u*1.6f,v*1.6f);float wind=Mathf.Sin(x*.12f+z*.018f+Mathf.PerlinNoise(x*.01f+5,z*.01f+5)*5)*.035f;Color c=Color.Lerp(Hex("#866A54"),Hex("#B68D65"),Mathf.Clamp01(n+wind));float d=RouteDistance(new Vector2(x,z));float wear=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.5f,3.3f+Mathf.PerlinNoise(x*.4f+30,z*.4f+30)*.8f,d));return Color.Lerp(c,Hex("#B19779")*(.88f+n*.18f),wear*.65f);},false,true);
