 var normal=Texture("Regolith_MicroNormal_256",256,(u,v)=>{float e=1/256f,dx=(Noise(u+e,v)-Noise(u-e,v))*.75f,dy=(Noise(u,v+e)-Noise(u,v-e))*.75f;Vector3 n=new Vector3(-dx,-dy,1).normalized;return new Color(n.x*.5f+.5f,n.y*.5f+.5f,n.z*.5f+.5f,1);},true);
 mats["Mars_Regolith"].SetColor("_BaseColor",Color.white);mats["Mars_Regolith"].SetTexture("_BaseMap",macro);mats["Mars_Regolith"].SetTexture("_DetailAlbedoMap",detail);mats["Mars_Regolith"].SetTextureScale("_DetailAlbedoMap",new Vector2(125,125));mats["Mars_Regolith"].SetTexture("_DetailNormalMap",normal);mats["Mars_Regolith"].SetFloat("_DetailNormalMapScale",.45f);mats["Mars_Regolith"].EnableKeyword("_DETAIL_MULX2");
 var rocktex=Texture("Basalt_Surface_512",512,(u,v)=>Color.Lerp(Hex("#54504B"),Hex("#8B7C68"),Noise(u,v)*.6f));mats["Mars_Rock_Basaltic"].SetColor("_BaseColor",Color.white);mats["Mars_Rock_Basaltic"].SetTexture("_BaseMap",rocktex);mats["Mars_Rock_Basaltic"].SetTexture("_BumpMap",normal);mats["Mars_Rock_Basaltic"].SetFloat("_BumpScale",.4f);mats["Mars_Rock_Basaltic"].EnableKeyword("_NORMALMAP");
 var layered=Texture("Delta_Bedding_512",512,(u,v)=>{float wave=Mathf.Sin(v*145+Mathf.PerlinNoise(u*8,v*3)*.7f);float bands=.5f+.5f*wave;return Color.Lerp(Hex("#6F6254"),Hex("#A88E70"),bands*.4f+Noise(u,v)*.4f);});mats["Mars_Rock_Layered"].SetColor("_BaseColor",Color.white);mats["Mars_Rock_Layered"].SetTexture("_BaseMap",layered);
 var paint=Texture("Composite_DustPaint_512",512,(u,v)=>{float dust=(1-v)*.10f+Noise(u,v)*.04f;return Color.Lerp(Color.white,Hex("#9D8669"),dust);});mats["Habitat_OffWhite"].SetTexture("_BaseMap",paint);
 var solar=Texture("Solar_Cells_Dust_512",512,(u,v)=>{float gx=u*12,gy=v*6;float fx=gx-Mathf.Floor(gx),fy=gy-Mathf.Floor(gy);bool seam=fx<.024f||fy<.025f;bool bus=Mathf.Abs(fx-.33f)<.012f||Mathf.Abs(fx-.66f)<.012f;var c=seam?Hex("#9CA5A0"):bus?Hex("#6B8187"):Color.Lerp(Hex("#253B46"),Hex("#445A63"),Noise(u,v));return Color.Lerp(c,Hex("#A38A6C"),Mathf.Pow(Noise(u*2,v*2),3)*.18f);});mats["SolarPanel"].SetColor("_BaseColor",Color.white);mats["SolarPanel"].SetTexture("_BaseMap",solar);
