 // Original block-stencil markings built as geometry, no external font/branding asset.
 static void Mark(Transform p,Vector3 center,string label,float size){string[] glyphs=label.Select(ch=>ch=='H'?"101101111101101":ch=='R'?"110101110101101":ch=='0'?"111101101101111":ch=='1'?"010110010010111":"111001111100111").ToArray();float width=label.Length*size*.8f;for(int l=0;l<glyphs.Length;l++)for(int y=0;y<5;y++)for(int x=0;x<3;x++)if(glyphs[l][y*3+x]=='1')Box("Stencil_"+label,center+new Vector3(-width/2+l*size*.8f+x*size*.19f,(2-y)*size*.19f,0),new Vector3(size*.16f,size*.16f,.025f),"Habitat_OffWhite",p);}
