 // Merge authored pieces by shared material per module. Collider children are retained and stripped of render components.
 static void Combine(Transform p,string folder){var filters=p.GetComponentsInChildren<MeshFilter>().Where(t=>t.GetComponent<MeshRenderer>()!=null).ToArray();var groups=filters.GroupBy(t=>t.GetComponent<MeshRenderer>().sharedMaterial).ToArray();foreach(var gr in groups){if(gr.Count()==0)continue;var instances=gr.Select(t=>new CombineInstance{mesh=t.sharedMesh,transform=p.worldToLocalMatrix*t.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{name=p.name+"_"+gr.Key.name+"_Combined",indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(instances,true,true);mesh.RecalculateBounds();SaveMesh(mesh,folder);var result=MeshGO(gr.Key.name+"_StaticAssembly",mesh,gr.Key,p,Vector3.zero,Vector3.one);result.transform.localPosition=Vector3.zero;result.transform.localRotation=Quaternion.identity;foreach(var mf in gr){var obj=mf.gameObject;UnityEngine.Object.DestroyImmediate(obj.GetComponent<MeshRenderer>());UnityEngine.Object.DestroyImmediate(mf);if(obj.GetComponent<Collider>()==null && obj.transform.childCount==0)UnityEngine.Object.DestroyImmediate(obj);}}
 }
