 static void Wayfinding(){var rt=root.Find("03_MissionRoute_4mClearCorridor");foreach(var lr in rt.GetComponentsInChildren<LineRenderer>())UnityEngine.Object.DestroyImmediate(lr.gameObject);foreach(var r in rt.GetComponentsInChildren<Renderer>())UnityEngine.Object.DestroyImmediate(r.gameObject);rt.name="03_ApprovedRoute_Waypoints_421p62m";var posts=Group("UtilityRoutePosts",root);var seen=new List<Vector2>();for(int i=0;i<route.Length-1;i++){var a=route[i];var b=route[i+1];var d=(b-a).normalized;int steps=Mathf.CeilToInt(Vector2.Distance(a,b)/22);for(int j=0;j<steps;j++){var q=Vector2.Lerp(a,b,(float)j/steps)+new Vector2(-d.y,d.x)*3.2f;if(seen.Any(t=>Vector2.Distance(t,q)<8))continue;seen.Add(q);Box("GroundedRoutePost",At(q.x,q.y,.42f),new Vector3(.12f,.84f,.12f),"Metal_Industrial",posts);Box("CyanReflector",At(q.x,q.y,.74f),new Vector3(.14f,.12f,.14f),"Accent_Cyan",posts);}}Combine(posts,"Props");}
