 public static void Polish(){Open();var remap=new Dictionary<Mesh,Mesh>();for(int i=0;i<3;i++){var old=AssetDatabase.LoadAssetAtPath<Mesh>(F+"/Rocks/LayeredDelta_LOD"+i+".asset");var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(F+"/Rocks/DeltaFractured_LOD"+i+".asset");var vs=mesh.vertices;for(int k=0;k<vs.Length;k++){// More fractured, flat-sided terrace silhouette, not a rounded dome.
 float x=vs[k].x,z=vs[k].z;vs[k].x=Mathf.Sign(x)*Mathf.Pow(Mathf.Abs(x),.72f);vs[k].z=Mathf.Sign(z)*Mathf.Pow(Mathf.Abs(z),.72f);}
 mesh.vertices=vs;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);remap[old]=mesh;}
 foreach(var mf in root.GetComponentsInChildren<MeshFilter>())if(remap.TryGetValue(mf.sharedMesh,out var replacement))mf.sharedMesh=replacement;
 var prefab=PrefabUtility.LoadPrefabContents(F+"/Prefabs/LayeredDelta.prefab");foreach(var mf in prefab.GetComponentsInChildren<MeshFilter>())if(remap.TryGetValue(mf.sharedMesh,out var replacement))mf.sharedMesh=replacement;PrefabUtility.SaveAsPrefabAsset(prefab,F+"/Prefabs/LayeredDelta.prefab");PrefabUtility.UnloadPrefabContents(prefab);
 foreach(var t in zones.Find("D_LayeredDeltaTerrain").GetComponentsInChildren<Transform>()){var col=t.GetComponent<BoxCollider>();if(col){var mf=t.GetComponentInChildren<MeshFilter>();col.center=mf.sharedMesh.bounds.center;col.size=mf.sharedMesh.bounds.size;}}
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Validate();Capture();Debug.Log("ASTROGATEWAY_ART_POLISHED");
