 public static void Grounding(){Open();Physics.SyncTransforms();foreach(var t in zones.Find("D_LayeredDeltaTerrain").GetComponentsInChildren<Transform>()){if(!t.name.StartsWith("DeltaTerrace_"))continue;var col=t.GetComponent<BoxCollider>();var b=col.bounds;float min=100;for(int x=0;x<=4;x++)for(int z=0;z<=4;z++){float wx=Mathf.Lerp(b.min.x,b.max.x,x/4f),wz=Mathf.Lerp(b.min.z,b.max.z,z/4f);if(ground.Raycast(new Ray(new Vector3(wx,30,wz),Vector3.down),out var hit,40))min=Mathf.Min(min,hit.point.y);}if(min<100)t.position=new Vector3(t.position.x,min-.35f,t.position.z);}
 EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Validate();Capture();Debug.Log("ASTROGATEWAY_GROUNDING_OK");
 }


 public static void Reopen(){EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Single);var type=typeof(EditorApplication).Assembly.GetType("UnityEditor.LogEntries");type?.GetMethod("Clear",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static)?.Invoke(null,null);Validate();Capture();var args=new object[]{0,0,0};type?.GetMethod("GetCounts",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static)?.Invoke(null,args);File.WriteAllText(O+"/Scene_Reopen_Status.txt","Reopened saved scene in Unity "+Application.unityVersion+"\nConsole after clearing earlier resolved authoring messages and validating: errors="+args[0]+", warnings="+args[1]+", logs="+args[2]+"\n");Debug.Log("ASTROGATEWAY_ART_REOPEN_OK");}


 public static void FramePower(){Open();var t=cameras.Find("View_C_SolarPower");t.position=At(40,-72,1.7f);t.LookAt(At(48,-42,1.4f));t.GetComponent<Camera>().fieldOfView=74;var smallPath=F+"/Prefabs/RegolithStone.prefab";if(!File.Exists(smallPath)){var stone=MeshGO("RegolithStone",AssetDatabase.LoadAssetAtPath<Mesh>(F+"/Rocks/AngularBasalt_LOD2.asset"),AssetDatabase.LoadAssetAtPath<Material>(F+"/Materials/Mars_Rock_Basaltic.mat"),null,Vector3.zero,new Vector3(.2f,.11f,.2f));PrefabUtility.SaveAsPrefabAsset(stone,smallPath);UnityEngine.Object.DestroyImmediate(stone);}EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Validate();Capture();Debug.Log("ASTROGATEWAY_POWER_FRAME_OK");}

 static Scene Open(){var s=SceneManager.GetSceneByPath(ScenePath);if(!s.isLoaded)s=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Single);SceneManager.SetActiveScene(s);root=s.GetRootGameObjects().Single(t=>t.name=="MarsOutpost_Environment_v01_1unit_1meter").transform;terrain=root.Find("01_Terrain_250x250m");zones=root.Find("02_EnvironmentZones");ground=terrain.GetComponentInChildren<MeshCollider>();cameras=root.Find("05_CompositionValidationCameras");return s;}
 [MenuItem("AstroGateway/Environment/Validate")]
 public static void Validate(){Open();Physics.SyncTransforms();var errors=new List<string>();var names=new[]{"H_CommandHabitat","G_Greenhouse","R_RoverBay","P_PowerStation","S_SolarArray","C_ScienceStaging","D_LayeredDeltaTerrain","B_DarkRockComparison"};var ledger=new List<string>();for(int i=0;i<names.Length;i++){var z=zones.Find(names[i]);if(!z||Vector3.Distance(z.position,At(centers[i].x,centers[i].y))>.01f)errors.Add("Zone displaced "+names[i]);ledger.Add(names[i]+": "+(z?z.position.ToString("F2"):"MISSING"));}foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)errors.Add("Missing script "+t.name);foreach(var rend in root.GetComponentsInChildren<Renderer>())foreach(var m in rend.sharedMaterials)if(!m||!m.shader||!m.shader.isSupported)errors.Add("Missing/unsupported material "+rend.name);var obstacles=root.GetComponentsInChildren<Collider>().Where(t=>t!=ground).ToArray();float length=0,maxSlope=0;int samples=0;for(int i=0;i<route.Length-1;i++){int n=Mathf.CeilToInt(Vector2.Distance(route[i],route[i+1])/.5f);Vector3 prev=Vector3.zero;for(int j=0;j<=n;j++){var q=Vector2.Lerp(route[i],route[i+1],(float)j/n);var pos=At(q.x,q.y);if(!ground.Raycast(new Ray(pos+Vector3.up*5,Vector3.down),out var hit,10)){errors.Add("Missing ground "+q);continue;}pos=hit.point;if(j>0){length+=Vector3.Distance(prev,pos);maxSlope=Mathf.Max(maxSlope,Mathf.Atan2(Mathf.Abs(pos.y-prev.y),new Vector2(pos.x-prev.x,pos.z-prev.z).magnitude)*Mathf.Rad2Deg);}prev=pos;samples++;foreach(var col in obstacles){var b=col.bounds;b.Expand(new Vector3(4,0,4));if(b.Contains(pos+Vector3.up*.5f))errors.Add("4m route obstruction "+col.name+" at "+q);}}}if(Mathf.Abs(length-421.62f)>.06f)errors.Add("Route distance changed "+length);if(maxSlope>12)errors.Add("Route slope "+maxSlope);var sight=new List<string>();Sight("Spawn to power mast",At(-45,-60,1.8f),At(25,-45,5.5f),sight);Sight("Spawn to delta silhouette",At(-45,-60,1.8f),At(0,114,2),sight);Sight("Delta to habitat roof",At(15,70,1.8f),At(-65,-60,3.8f),sight);if(sight.Any(t=>t.Contains("OBSTRUCTED")))errors.Add("Sightline blocked");var bounds=ground.sharedMesh.bounds;if(Mathf.Abs(bounds.size.x-250)>.01f||Mathf.Abs(bounds.size.z-250)>.01f)errors.Add("Bounds changed");
 File.WriteAllText(O+"/Geometry_Validation.md","# Stage 04 validation\n\nUnity "+Application.unityVersion+"; pipeline "+GraphicsSettings.currentRenderPipeline+"\n\nWorld: 250 × 250 m.\n\n"+string.Join("\n",ledger)+"\n\nActual mesh sampled route: "+length.ToString("F2")+" m; "+samples+" samples; max slope "+maxSlope.ToString("F2")+"°. At 2.5 m/s: "+(length/2.5f).ToString("F1")+" seconds, excluding interactions.\n\n"+string.Join("\n",sight)+"\n\nErrors: "+errors.Count+"\n"+string.Join("\n",errors.Distinct())+"\n\nClearance is a conservative expanded-collider bounds check; no controller or human walking test.\n");Stats();if(errors.Count>0)throw new Exception(string.Join("\n",errors.Distinct()));Debug.Log("ASTROGATEWAY_ART_VALIDATION_OK");}
 static void Sight(string n,Vector3 a,Vector3 b,List<string> output){var hits=Physics.RaycastAll(a,(b-a).normalized,Vector3.Distance(a,b)-.5f).Where(h=>h.collider.transform.IsChildOf(root)).OrderBy(h=>h.distance).ToArray();bool target=hits.Length>0&&((n.Contains("delta")&&hits[0].collider.name.StartsWith("DeltaTerrace"))||(n.Contains("habitat")&&hits[0].collider.name=="HabitatH01_PressureShell"));output.Add(n+": "+(hits.Length==0?"clear":target?"visible (target first hit)":"OBSTRUCTED by "+hits[0].collider.name));}
 static void Stats(){var meshes=root.GetComponentsInChildren<MeshFilter>().Select(t=>t.sharedMesh).Where(t=>t).Distinct().ToArray();var matsUsed=root.GetComponentsInChildren<Renderer>().SelectMany(t=>t.sharedMaterials).Where(t=>t).Distinct().ToArray();var tex=matsUsed.SelectMany(t=>t.GetTexturePropertyNames().Select(k=>t.GetTexture(k))).Where(t=>t).Distinct().ToArray();long meshmem=meshes.Sum(t=>Profiler.GetRuntimeMemorySizeLong(t));long texmem=tex.Sum(t=>Profiler.GetRuntimeMemorySizeLong(t));var txt="# Measured Editor asset inventory\n\n"+root.GetComponentsInChildren<Renderer>().Length+" renderers (includes inactive alternative LOD renderers), "+root.GetComponentsInChildren<LODGroup>().Length+" LOD groups; "+matsUsed.Length+" shared surface materials.\n\n"+meshes.Sum(t=>(long)t.vertexCount)+" vertices / "+meshes.Sum(t=>(long)t.triangles.Length/3)+" triangles across unique referenced mesh assets, all LOD levels combined. These are not camera-visible frame counts.\n\nProfiler.GetRuntimeMemorySizeLong: unique mesh objects "+meshmem+" bytes; unique referenced texture objects "+texmem+" bytes. Editor platform-dependent resident-object estimates, not Web GPU or total scene memory.\n\n|Mesh|Vertices|Triangles|\n|---|---:|---:|\n"+string.Join("\n",meshes.OrderBy(t=>t.name).Select(t=>"|"+t.name+"|"+t.vertexCount+"|"+t.triangles.Length/3+"|"))+"\n\nTexture inventory:\n"+string.Join("\n",tex.Select(t=>t.name+" "+t.width+"×"+t.height+" "+Profiler.GetRuntimeMemorySizeLong(t)+" bytes"));File.WriteAllText(O+"/Asset_Statistics.md",txt);}
 [MenuItem("AstroGateway/Environment/Capture")]
 public static void Capture(){Open();foreach(var cam in cameras.GetComponentsInChildren<Camera>()){var rt=new RenderTexture(1600,900,24);rt.Create();var request=new UniversalRenderPipeline.SingleCameraRequest{destination=rt};RenderPipeline.SubmitRenderRequest(cam,request);var prior=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes(O+"/"+cam.name+".png",t.EncodeToPNG());RenderTexture.active=prior;UnityEngine.Object.DestroyImmediate(t);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}File.WriteAllText(O+"/capture-status.txt",DateTime.UtcNow.ToString("o"));Debug.Log("ASTROGATEWAY_ART_CAPTURE_OK");}
 [MenuItem("AstroGateway/Environment/Build Web")]
 public static void BuildWeb(){Open();var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{ScenePath},locationPathName=O+"/Web",target=BuildTarget.WebGL,options=BuildOptions.None});File.WriteAllText(O+"/Web_Build_Status.txt",report.summary.result+"\nErrors: "+report.summary.totalErrors+"\nWarnings: "+report.summary.totalWarnings+"\nBytes: "+report.summary.totalSize);if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Web build failed");Debug.Log("ASTROGATEWAY_ART_WEB_BUILD_OK");}
